def compute(vars):
    shares = vars["v1"]
    exercise_price = vars["v2"]
    cash_impact = shares * exercise_price

    return {
        "value": cash_impact,
        "trace": {
            "shares": shares,
            "exercise_price_per_share": exercise_price,
            "output_meta": {
                "currency": "USD",
                "scale": "ones",
                "unit": "currency"
            }
        }
    }
